#!/usr/bin/env node
// crear-arcredix.mjs
// Crea ARCREDIX (landing + login + super-admin + portal del dueno + caja) en un proyecto Next.js.
//
// Uso (desde la raiz de un proyecto Next.js NUEVO, donde esta package.json):
//   node crear-arcredix.mjs
// Opciones:
//   --force       sobrescribe archivos que ya existan
//   --no-install  no instala dependencias

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { execSync } from "node:child_process";

const args = process.argv.slice(2);
const FORCE = args.includes("--force");
const NO_INSTALL = args.includes("--no-install");
const root = process.cwd();

const log = (m) => console.log(m);
const ok = (m) => console.log("  [ok] " + m);
const skip = (m) => console.log("  [omitido] " + m);

const pkgPath = path.join(root, "package.json");
if (!fs.existsSync(pkgPath)) {
  console.error("No encuentro package.json. Ejecuta este script en la raiz de tu proyecto Next.js.");
  process.exit(1);
}
const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
const nextVersion = (pkg.dependencies && pkg.dependencies.next) || (pkg.devDependencies && pkg.devDependencies.next);
if (!nextVersion) {
  console.error("Este proyecto no tiene Next.js en package.json.");
  process.exit(1);
}
const nextMajor = parseInt(String(nextVersion).replace(/[^0-9.]/g, "").split(".")[0], 10) || 15;
if (nextMajor < 15) {
  console.error("Se necesita Next.js 15 o superior (tu version: " + nextVersion + "). Actualiza: npm i next@latest react@latest react-dom@latest");
  process.exit(1);
}
if (fs.existsSync(path.join(root, "src", "app")) && !fs.existsSync(path.join(root, "app"))) {
  console.error("Tu proyecto usa src/. Este script escribe en app/ y lib/ de la raiz. Crea el proyecto sin carpeta src.");
  process.exit(1);
}

const TEXT_FILES = {
 "components/VoiceDemo.tsx": "\"use client\";\n\nimport { useState } from \"react\";\n\nconst SAMPLES = [\n  { amount: 15000, who: \"María González\" },\n  { amount: 48500, who: \"Carlos Benítez\" },\n  { amount: 7250.5, who: \"Lucía Fernández\" },\n  { amount: 126000, who: \"Distribuidora Del Sur\" },\n];\n\nexport function VoiceDemo() {\n  const [n, setN] = useState<number | null>(null);\n  const [unsupported, setUnsupported] = useState(false);\n\n  function play() {\n    const i = n === null ? 0 : (n + 1) % SAMPLES.length;\n    setN(i);\n    const s = SAMPLES[i];\n    if (!(\"speechSynthesis\" in window)) {\n      setUnsupported(true);\n      return;\n    }\n    const pesos = Math.floor(s.amount);\n    const cents = Math.round((s.amount - pesos) * 100);\n    const text = `Ingresó una transferencia de ${pesos.toLocaleString(\"es-AR\")} pesos${cents ? ` con ${cents} centavos` : \"\"} de ${s.who}`;\n    const u = new SpeechSynthesisUtterance(text);\n    u.lang = \"es-AR\";\n    window.speechSynthesis.cancel();\n    window.speechSynthesis.speak(u);\n  }\n\n  const s = n === null ? null : SAMPLES[n];\n  return (\n    <div className=\"mx-auto max-w-md rounded-2xl border border-[#00cba6]/30 bg-white/5 p-5 text-center\">\n      <p className=\"text-sm text-white/60\">Simulador de caja</p>\n      <div className=\"my-4 min-h-24 rounded-xl border border-[#00cba6]/50 bg-[#00cba6]/10 p-4\">\n        {s ? (\n          <>\n            <p className=\"text-3xl font-bold text-[#00cba6]\">\n              {s.amount.toLocaleString(\"es-AR\", { style: \"currency\", currency: \"ARS\" })}\n            </p>\n            <p className=\"mt-1 text-white/80\">{s.who} · acreditado</p>\n          </>\n        ) : (\n          <p className=\"pt-5 text-white/50\">Tocá el botón para escuchar un cobro</p>\n        )}\n      </div>\n      <button onClick={play} className=\"w-full rounded-lg bg-[#00cba6] px-4 py-3 font-semibold text-[#00070f]\">\n        Escuchar cómo suena un cobro\n      </button>\n      {unsupported && <p className=\"mt-2 text-xs text-white/50\">Tu navegador no soporta voz. Probá con Chrome o Safari.</p>}\n    </div>\n  );\n}\n",
 "components/ActionForm.tsx": "\"use client\";\n\nimport { useActionState, useRef, type ReactNode } from \"react\";\n\nexport type FormResult = { ok?: string; error?: string } | undefined;\n\nexport function ActionForm({\n  action,\n  children,\n  submit,\n  resetOnOk = true,\n  className = \"\",\n}: {\n  action: (prev: FormResult, fd: FormData) => Promise<FormResult>;\n  children: ReactNode;\n  submit: string;\n  resetOnOk?: boolean;\n  className?: string;\n}) {\n  const ref = useRef<HTMLFormElement>(null);\n  const [state, formAction, pending] = useActionState(async (prev: FormResult, fd: FormData) => {\n    const r = await action(prev, fd);\n    if (r?.ok && resetOnOk) ref.current?.reset();\n    return r;\n  }, undefined);\n\n  return (\n    <form ref={ref} action={formAction} className={className}>\n      <div className=\"flex flex-wrap items-end gap-2\">\n        {children}\n        <button disabled={pending} className=\"rounded-lg bg-[#00cba6] px-4 py-2 font-semibold text-[#00070f] disabled:opacity-60\">\n          {pending ? \"...\" : submit}\n        </button>\n      </div>\n      {state?.error && <p className=\"mt-2 text-sm text-red-400\">{state.error}</p>}\n      {state?.ok && <p className=\"mt-2 text-sm text-[#00cba6]\">{state.ok}</p>}\n    </form>\n  );\n}\n\nexport const inputCls =\n  \"rounded-lg border border-white/15 bg-white/5 px-3 py-2 text-white placeholder:text-white/40 outline-none focus:border-[#00cba6]\";\n",
 "app/page.tsx": "import Image from \"next/image\";\nimport Link from \"next/link\";\nimport { PLANS, type PlanId } from \"@/lib/plans\";\nimport { buyLink } from \"@/lib/config\";\nimport { VoiceDemo } from \"@/components/VoiceDemo\";\n\nconst accent = \"text-[#00cba6]\";\n\nconst FEATURES: Record<PlanId, string[]> = {\n  starter: [\"1 usuario dueño + 1 vista de caja\", \"1 billetera o banco vinculado\", \"Aviso automático por voz en vivo\", \"Bloqueo anti-doble gasto\", \"Historial de 30 días\"],\n  pro: [\"Dueño + hasta 4 cajas simultáneas con PIN\", \"Hasta 3 bancos, billeteras o alias\", \"Escáner de comprobantes por cámara\", \"Historial ilimitado\", \"Exportación de cierres diarios\"],\n  enterprise: [\"Cajas y usuarios ilimitados\", \"Múltiples sucursales y cuentas\", \"Alertas de anomalías y auditoría por cajero\", \"Soporte prioritario por WhatsApp\"],\n  lifetime: [\"Instancia propia en tu dominio\", \"Hasta 3 cuentas o alias vinculados\", \"Reglas de reenvío bancario configuradas\", \"Capacitación al personal de caja\", \"30 días de garantía de puesta en marcha\"],\n};\n\nexport default function Home() {\n  return (\n    <>\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between p-4\">\n        <span className=\"text-lg font-extrabold tracking-wide\">ARCREDIX<span className={accent}>®</span></span>\n        <div className=\"flex gap-4 text-sm\">\n          <a href=\"#planes\" className=\"text-white/70 hover:text-white\">Planes</a>\n          <Link href=\"/caja/login\" className=\"text-white/70 hover:text-white\">Caja</Link>\n          <Link href=\"/login\" className=\"rounded-lg border border-[#00cba6] px-3 py-1.5 text-[#00cba6]\">Ingresar</Link>\n        </div>\n      </nav>\n\n      <header className=\"mx-auto max-w-5xl px-4 pt-6 text-center\">\n        <Image src=\"/arcredix-logo.webp\" alt=\"ARCREDIX: validá tus cobros, evitá estafas\" width={1200} height={400} priority className=\"mx-auto w-full max-w-3xl rounded-2xl\" />\n        <h1 className=\"mx-auto mt-8 max-w-3xl text-3xl font-extrabold sm:text-5xl\">\n          Un comprobante editado <span className={accent}>no te vuelve a engañar</span>\n        </h1>\n        <p className=\"mx-auto mt-4 max-w-2xl text-lg text-white/70\">\n          ARCREDIX no confía en la imagen que te muestra el cliente: confirma cada cobro con el aviso real de tu banco o billetera, te lo dice en voz alta en caja y bloquea los comprobantes que ya se usaron.\n        </p>\n        <div className=\"mt-6 flex flex-wrap justify-center gap-3\">\n          <a href=\"#planes\" className=\"rounded-lg bg-[#00cba6] px-6 py-3 font-semibold text-[#00070f]\">Ver planes</a>\n          <a href=\"#probalo\" className=\"rounded-lg border border-white/20 px-6 py-3\">Probalo en vivo</a>\n        </div>\n      </header>\n\n      <section id=\"probalo\" className=\"mx-auto max-w-5xl px-4 py-16\">\n        <h2 className=\"mb-6 text-center text-2xl font-bold\">Escuchá cómo suena un cobro en tu caja</h2>\n        <VoiceDemo />\n      </section>\n\n      <section className=\"mx-auto max-w-6xl px-4 py-8\">\n        <h2 className=\"mb-8 text-center text-2xl font-bold\">Cómo funciona (menos de 3 segundos)</h2>\n        <div className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-4\">\n          {[\n            [\"1\", \"El cliente transfiere\", \"Paga al alias o CVU de tu local desde su billetera o banco.\"],\n            [\"2\", \"Llega la confirmación real\", \"Tu banco o Mercado Pago avisa y ARCREDIX registra el cobro como disponible.\"],\n            [\"3\", \"Aviso por voz en caja\", \"La pantalla lo anuncia en voz alta con el monto y quién pagó.\"],\n            [\"4\", \"Validar y entregar\", \"Al validarlo queda bloqueado: si alguien reusa ese comprobante, salta la alerta.\"],\n          ].map(([n, t, d]) => (\n            <div key={n} className=\"rounded-xl border border-white/10 bg-white/5 p-5\">\n              <p className={`text-3xl font-extrabold ${accent}`}>{n}</p>\n              <h3 className=\"mt-2 font-semibold\">{t}</h3>\n              <p className=\"mt-1 text-sm text-white/70\">{d}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      <section className=\"mx-auto max-w-6xl px-4 py-12\">\n        <div className=\"grid gap-4 sm:grid-cols-3\">\n          {[\n            [\"Para el dueño\", \"Cargá tus alias, vinculá Mercado Pago, creá PINs para tus cajeros y exportá el historial a Excel.\"],\n            [\"Para el cajero\", \"Una pantalla simple: ingresos en vivo, aviso por voz y verificación por número de operación. Sin saldos ni reportes.\"],\n            [\"Para vos, que vendés\", \"Un panel para dar de alta comercios, asignar planes y suspender el acceso si no renuevan.\"],\n          ].map(([t, d]) => (\n            <div key={t} className=\"rounded-xl border border-white/10 p-5\">\n              <h3 className={`font-semibold ${accent}`}>{t}</h3>\n              <p className=\"mt-2 text-sm text-white/70\">{d}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      <section id=\"planes\" className=\"mx-auto max-w-6xl px-4 py-16\">\n        <h2 className=\"text-center text-3xl font-extrabold\">Planes en dólares</h2>\n        <p className=\"mt-2 text-center text-white/60\">Todos los valores en USD.</p>\n        <div className=\"mt-10 grid gap-4 md:grid-cols-2 lg:grid-cols-4\">\n          {(Object.keys(PLANS) as PlanId[]).map((id) => {\n            const p = PLANS[id];\n            const featured = id === \"pro\";\n            return (\n              <div key={id} className={`flex flex-col rounded-2xl border p-5 ${featured ? \"border-[#00cba6] bg-[#00cba6]/10\" : \"border-white/10 bg-white/5\"}`}>\n                {featured && <span className={`mb-2 text-xs font-bold uppercase ${accent}`}>Más vendido</span>}\n                <h3 className=\"text-lg font-bold\">{p.name}</h3>\n                <p className=\"mt-3 text-3xl font-extrabold\">\n                  {p.priceMonthly ? <>USD {p.priceMonthly}<span className=\"text-base font-normal text-white/60\"> / mes</span></> : <>USD {p.setup}<span className=\"text-base font-normal text-white/60\"> pago único</span></>}\n                </p>\n                {p.priceMonthly ? (\n                  <p className=\"text-sm text-white/60\">+ USD {p.setup} de setup único (opcional)</p>\n                ) : (\n                  <p className=\"text-sm text-white/60\">Cero abonos mensuales</p>\n                )}\n                <ul className=\"mt-4 flex-1 space-y-2 text-sm text-white/80\">\n                  {FEATURES[id].map((f) => (<li key={f}>✓ {f}</li>))}\n                </ul>\n                <a href={buyLink(p.name)} className={`mt-5 rounded-lg px-4 py-2.5 text-center font-semibold ${featured ? \"bg-[#00cba6] text-[#00070f]\" : \"border border-white/20\"}`}>\n                  Contratar\n                </a>\n              </div>\n            );\n          })}\n        </div>\n        <p className=\"mt-6 text-center text-sm text-white/50\">\n          Si preferís no pagar abonos, la Licencia Propia te da tu instancia sin cuotas mensuales. Las actualizaciones futuras se cotizan por ajuste.\n        </p>\n      </section>\n\n      <footer id=\"contacto\" className=\"border-t border-white/10 py-8 text-center text-sm text-white/50\">\n        © 2026 ARCREDIX® · Validá tus cobros. Evitá estafas.\n      </footer>\n    </>\n  );\n}\n",
 "app/layout.tsx": "import type { Metadata } from \"next\";\nimport \"./globals.css\";\n\nexport const metadata: Metadata = {\n  title: \"ARCREDIX | Validá tus cobros. Evitá estafas.\",\n  description:\n    \"Confirmá cada transferencia contra la fuente real (tu banco o billetera), con aviso por voz en caja y bloqueo de comprobantes repetidos.\",\n};\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"es\">\n      <body>\n        <div\n          className=\"min-h-screen bg-[#00070f] text-white antialiased\"\n          style={{ fontFamily: \"ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif\" }}\n        >\n          {children}\n        </div>\n      </body>\n    </html>\n  );\n}\n",
 "app/admin/actions.ts": "\"use server\";\n\nimport bcrypt from \"bcryptjs\";\nimport { revalidatePath } from \"next/cache\";\nimport { redirect } from \"next/navigation\";\nimport { z } from \"zod\";\nimport { sql } from \"@/lib/db\";\nimport { generateCommerceCode, generateToken } from \"@/lib/codes\";\nimport { isPlanId } from \"@/lib/plans\";\nimport { destroySession, requireAdmin } from \"@/lib/session\";\n\ntype Result = { ok?: string; error?: string } | undefined;\n\nconst createSchema = z.object({\n  name: z.string().trim().min(2).max(100),\n  email: z.string().trim().toLowerCase().email(),\n  password: z.string().min(8).max(100),\n  plan: z.string().refine(isPlanId, \"Plan inválido\"),\n  expires: z.string().optional(),\n});\n\nexport async function createCommerce(_prev: Result, fd: FormData): Promise<Result> {\n  await requireAdmin();\n  const parsed = createSchema.safeParse({\n    name: fd.get(\"name\"),\n    email: fd.get(\"email\"),\n    password: fd.get(\"password\"),\n    plan: fd.get(\"plan\"),\n    expires: (fd.get(\"expires\") as string) || undefined,\n  });\n  if (!parsed.success) return { error: \"Revisá los datos: nombre, email válido y contraseña de 8+ caracteres.\" };\n  const { name, email, password, plan, expires } = parsed.data;\n  const lifetime = fd.get(\"lifetime\") === \"on\" || plan === \"lifetime\";\n\n  const exists = await sql`select 1 from commerces where owner_email = ${email}`;\n  if (exists.length) return { error: \"Ya existe un comercio con ese email.\" };\n\n  const hash = await bcrypt.hash(password, 12);\n  const code = generateCommerceCode();\n  const token = generateToken();\n  await sql`insert into commerces (name, owner_email, owner_password_hash, plan, lifetime, expires_at, code, webhook_token)\n    values (${name}, ${email}, ${hash}, ${plan}, ${lifetime}, ${lifetime || !expires ? null : new Date(expires + \"T23:59:59\").toISOString()}, ${code}, ${token})`;\n\n  revalidatePath(\"/admin\");\n  return { ok: `Comercio creado. Código de caja: ${code}. Enviale al dueño su email y la contraseña temporal.` };\n}\n\nexport async function updateCommerce(fd: FormData): Promise<void> {\n  await requireAdmin();\n  const id = String(fd.get(\"id\") ?? \"\");\n  const plan = String(fd.get(\"plan\") ?? \"\");\n  if (!id || !isPlanId(plan)) return;\n  const lifetime = fd.get(\"lifetime\") === \"on\" || plan === \"lifetime\";\n  const expires = String(fd.get(\"expires\") ?? \"\");\n  await sql`update commerces set plan = ${plan}, lifetime = ${lifetime},\n    expires_at = ${lifetime || !expires ? null : new Date(expires + \"T23:59:59\").toISOString()}\n    where id = ${id}`;\n  revalidatePath(\"/admin\");\n}\n\nexport async function setStatus(id: string, status: \"active\" | \"suspended\"): Promise<void> {\n  await requireAdmin();\n  await sql`update commerces set status = ${status} where id = ${id}`;\n  revalidatePath(\"/admin\");\n}\n\nexport async function resetOwnerPassword(fd: FormData): Promise<void> {\n  await requireAdmin();\n  const id = String(fd.get(\"id\") ?? \"\");\n  const password = String(fd.get(\"password\") ?? \"\");\n  if (!id || password.length < 8) return;\n  const hash = await bcrypt.hash(password, 12);\n  await sql`update commerces set owner_password_hash = ${hash} where id = ${id}`;\n  revalidatePath(\"/admin\");\n}\n\nexport async function logoutAdmin() {\n  await destroySession(\"admin\");\n  redirect(\"/admin/login\");\n}\n",
 "app/admin/page.tsx": "import { Suspense } from \"react\";\nimport { sql } from \"@/lib/db\";\nimport { requireAdmin } from \"@/lib/session\";\nimport { PLANS, type PlanId } from \"@/lib/plans\";\nimport { money } from \"@/lib/format\";\nimport { ActionForm, inputCls } from \"@/components/ActionForm\";\nimport { createCommerce, logoutAdmin, resetOwnerPassword, setStatus, updateCommerce } from \"./actions\";\n\nexport const metadata = { title: \"Super-admin | ARCREDIX\", robots: { index: false, follow: false } };\n\nexport default function AdminPage() {\n  return (\n    <Suspense fallback={<main className=\"p-8 text-white/60\">Cargando...</main>}>\n      <AdminContent />\n    </Suspense>\n  );\n}\n\nasync function AdminContent() {\n  await requireAdmin();\n\n  const commerces = await sql`select c.id, c.name, c.owner_email, c.plan, c.status, c.lifetime, c.expires_at, c.code,\n      (select count(*)::int from payments p where p.commerce_id = c.id and p.received_at > now() - interval '30 days') as pay30\n    from commerces c order by c.created_at desc`;\n  const totals = await sql`select count(*)::int as n, coalesce(sum(amount),0) as total from payments\n    where received_at > now() - interval '30 days'`;\n\n  const active = commerces.filter((c) => c.status === \"active\");\n  const mrr = active\n    .filter((c) => !c.lifetime)\n    .reduce((acc, c) => acc + (PLANS[c.plan as PlanId]?.priceMonthly ?? 0), 0);\n\n  return (\n    <main className=\"mx-auto max-w-6xl space-y-8 p-6\">\n      <header className=\"flex items-center justify-between\">\n        <h1 className=\"text-2xl font-bold\">Super-admin</h1>\n        <form action={logoutAdmin}>\n          <button className=\"text-sm text-white/70 underline\">Cerrar sesión</button>\n        </form>\n      </header>\n\n      <section className=\"grid gap-3 sm:grid-cols-4\">\n        {[\n          [\"Comercios\", String(commerces.length)],\n          [\"Activos\", String(active.length)],\n          [\"Ingreso mensual (USD)\", `USD ${mrr}`],\n          [\"Operaciones 30 días\", String(totals[0].n)],\n        ].map(([k, v]) => (\n          <div key={k} className=\"rounded-xl border border-white/10 bg-white/5 p-4\">\n            <p className=\"text-xs text-white/60\">{k}</p>\n            <p className=\"mt-1 text-2xl font-bold text-[#00cba6]\">{v}</p>\n          </div>\n        ))}\n      </section>\n\n      <section className=\"rounded-xl border border-white/10 bg-white/5 p-4\">\n        <h2 className=\"mb-3 font-semibold\">Alta rápida de cliente</h2>\n        <ActionForm action={createCommerce} submit=\"Crear comercio\">\n          <input name=\"name\" required placeholder=\"Razón social / comercio\" className={inputCls} />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email del dueño\" className={inputCls} />\n          <input name=\"password\" required minLength={8} placeholder=\"Contraseña temporal\" className={inputCls} />\n          <select name=\"plan\" defaultValue=\"starter\" className={inputCls}>\n            {Object.entries(PLANS).map(([id, p]) => (\n              <option key={id} value={id} className=\"text-black\">{p.name}</option>\n            ))}\n          </select>\n          <label className=\"text-xs text-white/60\">\n            Vence\n            <input name=\"expires\" type=\"date\" className={inputCls + \" ml-2\"} />\n          </label>\n          <label className=\"flex items-center gap-1 text-sm\">\n            <input name=\"lifetime\" type=\"checkbox\" /> Licencia vitalicia\n          </label>\n        </ActionForm>\n      </section>\n\n      <section className=\"space-y-3\">\n        <h2 className=\"font-semibold\">Comercios</h2>\n        {commerces.length === 0 && <p className=\"text-white/60\">Todavía no hay comercios.</p>}\n        {commerces.map((c) => (\n          <div key={c.id as string} className=\"rounded-xl border border-white/10 bg-white/5 p-4\">\n            <div className=\"flex flex-wrap items-center justify-between gap-2\">\n              <div>\n                <p className=\"font-semibold\">{c.name as string}</p>\n                <p className=\"text-sm text-white/60\">\n                  {c.owner_email as string} · Código de caja: <span className=\"font-mono\">{c.code as string}</span> · {c.pay30 as number} operaciones (30 d)\n                </p>\n              </div>\n              <form action={setStatus.bind(null, c.id as string, c.status === \"active\" ? \"suspended\" : \"active\")}>\n                <button\n                  className={`rounded-lg px-3 py-1.5 text-sm font-semibold ${\n                    c.status === \"active\" ? \"bg-red-500/20 text-red-300\" : \"bg-[#00cba6]/20 text-[#00cba6]\"\n                  }`}\n                >\n                  {c.status === \"active\" ? \"Suspender\" : \"Reactivar\"}\n                </button>\n              </form>\n            </div>\n\n            <form action={updateCommerce} className=\"mt-3 flex flex-wrap items-center gap-2 text-sm\">\n              <input type=\"hidden\" name=\"id\" value={c.id as string} />\n              <select name=\"plan\" defaultValue={c.plan as string} className={inputCls}>\n                {Object.entries(PLANS).map(([id, p]) => (\n                  <option key={id} value={id} className=\"text-black\">{p.name}</option>\n                ))}\n              </select>\n              <input\n                name=\"expires\"\n                type=\"date\"\n                defaultValue={c.expires_at ? new Date(c.expires_at as string).toISOString().slice(0, 10) : \"\"}\n                className={inputCls}\n              />\n              <label className=\"flex items-center gap-1\">\n                <input name=\"lifetime\" type=\"checkbox\" defaultChecked={Boolean(c.lifetime)} /> Vitalicia\n              </label>\n              <button className=\"rounded-lg border border-white/20 px-3 py-1.5\">Guardar plan</button>\n            </form>\n\n            <form action={resetOwnerPassword} className=\"mt-2 flex flex-wrap items-center gap-2 text-sm\">\n              <input type=\"hidden\" name=\"id\" value={c.id as string} />\n              <input name=\"password\" minLength={8} placeholder=\"Nueva contraseña del dueño\" className={inputCls} />\n              <button className=\"rounded-lg border border-white/20 px-3 py-1.5\">Cambiar contraseña</button>\n            </form>\n          </div>\n        ))}\n        <p className=\"text-xs text-white/40\">Volumen procesado últimos 30 días: {money(totals[0].total as string)}</p>\n      </section>\n    </main>\n  );\n}\n",
 "app/admin/login/actions.ts": "\"use server\";\n\nimport bcrypt from \"bcryptjs\";\nimport { redirect } from \"next/navigation\";\nimport { sql } from \"@/lib/db\";\nimport { createSession } from \"@/lib/session\";\nimport { getIp, isBlocked, logAttempt } from \"@/lib/ratelimit\";\n\ntype State = { error?: string } | undefined;\n\nexport async function loginAdmin(_prev: State, formData: FormData): Promise<State> {\n  const email = String(formData.get(\"email\") ?? \"\").trim().toLowerCase();\n  const password = String(formData.get(\"password\") ?? \"\");\n  const ip = await getIp();\n\n  if (await isBlocked(ip, \"admin\")) return { error: \"Demasiados intentos. Esperá 15 minutos.\" };\n\n  const rows = await sql`select id, password_hash from admins where email = ${email} limit 1`;\n  const admin = rows[0];\n  const ok = admin ? await bcrypt.compare(password, admin.password_hash as string) : false;\n\n  await logAttempt(ip, \"admin\", ok);\n  if (!ok || !admin) return { error: \"Credenciales inválidas.\" };\n\n  await createSession(\"admin\", admin.id as string, 60 * 60 * 8);\n  redirect(\"/admin\");\n}\n",
 "app/admin/login/page.tsx": "\"use client\";\n\nimport { useActionState } from \"react\";\nimport { loginAdmin } from \"./actions\";\nimport { inputCls } from \"@/components/ActionForm\";\n\nexport default function AdminLogin() {\n  const [state, action, pending] = useActionState(loginAdmin, undefined);\n  return (\n    <main className=\"mx-auto max-w-sm p-8 pt-24\">\n      <h1 className=\"text-2xl font-bold\">Super-admin</h1>\n      <form action={action} className=\"mt-6 space-y-3\">\n        <input name=\"email\" type=\"email\" required placeholder=\"Email\" className={inputCls + \" w-full\"} />\n        <input name=\"password\" type=\"password\" required placeholder=\"Contraseña\" className={inputCls + \" w-full\"} />\n        {state?.error && <p className=\"text-sm text-red-400\">{state.error}</p>}\n        <button disabled={pending} className=\"w-full rounded-lg bg-[#00cba6] p-3 font-semibold text-[#00070f] disabled:opacity-60\">\n          {pending ? \"Verificando...\" : \"Entrar\"}\n        </button>\n      </form>\n    </main>\n  );\n}\n",
 "app/caja/actions.ts": "\"use server\";\n\nimport { redirect } from \"next/navigation\";\nimport { z } from \"zod\";\nimport { sql } from \"@/lib/db\";\nimport { destroySession, requireCashier } from \"@/lib/session\";\n\nexport type PaymentView = {\n  id: string;\n  externalId: string;\n  amount: number;\n  senderName: string;\n  status: string;\n  receivedAt: string;\n  validatedAt: string | null;\n};\n\nexport type ValidateResult = { ok: true } | { ok?: false; error: string; usedAt?: string | null };\nexport type VerifyResult =\n  | { found: false }\n  | { found: true; payment: PaymentView }\n  | { error: string };\n\nconst idSchema = z.string().uuid();\n\nexport async function validatePayment(id: string): Promise<ValidateResult> {\n  const { cashier, commerce } = await requireCashier();\n  if (commerce.blocked) return { error: commerce.blockReason ?? \"Cuenta bloqueada\" };\n  if (!idSchema.safeParse(id).success) return { error: \"Operación inválida.\" };\n\n  // Actualización atómica: solo UNA caja puede pasar un pago de DISPONIBLE a VALIDADO\n  const rows = await sql`update payments\n    set status = 'VALIDADO', validated_at = now(), validated_by = ${cashier.id}\n    where id = ${id} and commerce_id = ${commerce.id} and status = 'DISPONIBLE'\n    returning id`;\n  if (rows.length) return { ok: true };\n\n  const ex = await sql`select validated_at from payments where id = ${id} and commerce_id = ${commerce.id}`;\n  if (ex[0]) return { error: \"COMPROBANTE YA USADO\", usedAt: ex[0].validated_at ? String(ex[0].validated_at) : null };\n  return { error: \"No encontré ese pago.\" };\n}\n\nexport async function verifyOperation(op: string): Promise<VerifyResult> {\n  const { commerce } = await requireCashier();\n  if (commerce.blocked) return { error: commerce.blockReason ?? \"Cuenta bloqueada\" };\n  const clean = String(op ?? \"\").trim();\n  if (clean.length < 6 || clean.length > 40) return { error: \"Ingresá el número de operación completo.\" };\n\n  const rows = await sql`select id, external_id, amount, sender_name, status, received_at, validated_at\n    from payments where commerce_id = ${commerce.id} and external_id = ${clean} limit 1`;\n  const r = rows[0];\n  if (!r) return { found: false };\n  return {\n    found: true,\n    payment: {\n      id: r.id as string,\n      externalId: r.external_id as string,\n      amount: Number(r.amount),\n      senderName: r.sender_name as string,\n      status: r.status as string,\n      receivedAt: String(r.received_at),\n      validatedAt: r.validated_at ? String(r.validated_at) : null,\n    },\n  };\n}\n\nexport async function logoutCashier() {\n  await destroySession(\"cashier\");\n  redirect(\"/caja/login\");\n}\n",
 "app/caja/page.tsx": "import { Suspense } from \"react\";\nimport { requireCashier } from \"@/lib/session\";\nimport { logoutCashier } from \"./actions\";\nimport { CajaClient } from \"./caja-client\";\n\nexport const metadata = { title: \"Caja | ARCREDIX\", robots: { index: false, follow: false } };\n\nexport default function CajaPage() {\n  return (\n    <Suspense fallback={<main className=\"p-8 text-white/60\">Cargando...</main>}>\n      <CajaContent />\n    </Suspense>\n  );\n}\n\nasync function CajaContent() {\n  const { cashier, commerce } = await requireCashier();\n\n  if (commerce.blocked) {\n    return (\n      <main className=\"mx-auto max-w-xl p-8 pt-24 text-center\">\n        <h1 className=\"text-2xl font-bold\">{commerce.name}</h1>\n        <p className=\"mt-4 rounded-xl border border-red-400/40 bg-red-500/10 p-4 text-red-200\">\n          {commerce.blockReason} Avisale al dueño del comercio para renovar el servicio.\n        </p>\n        <form action={logoutCashier} className=\"mt-6\">\n          <button className=\"text-sm text-white/70 underline\">Salir</button>\n        </form>\n      </main>\n    );\n  }\n\n  return (\n    <main className=\"mx-auto max-w-3xl p-4\">\n      <header className=\"mb-4 flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-xl font-bold\">{commerce.name}</h1>\n          <p className=\"text-xs text-white/60\">Cajero: {cashier.name}</p>\n        </div>\n        <form action={logoutCashier}>\n          <button className=\"text-sm text-white/70 underline\">Salir</button>\n        </form>\n      </header>\n      <CajaClient ocr={commerce.plan.ocr} />\n    </main>\n  );\n}\n",
 "app/caja/caja-client.tsx": "\"use client\";\n\nimport { useCallback, useEffect, useRef, useState, useTransition } from \"react\";\nimport { validatePayment, verifyOperation, type PaymentView, type VerifyResult } from \"./actions\";\n\nconst money = (n: number) => n.toLocaleString(\"es-AR\", { style: \"currency\", currency: \"ARS\" });\nconst time = (d: string) => new Date(d).toLocaleTimeString(\"es-AR\", { hour: \"2-digit\", minute: \"2-digit\" });\nconst dt = (d: string) => new Date(d).toLocaleString(\"es-AR\", { dateStyle: \"short\", timeStyle: \"short\" });\n\nfunction speak(text: string) {\n  if (typeof window === \"undefined\" || !(\"speechSynthesis\" in window)) return;\n  const u = new SpeechSynthesisUtterance(text);\n  u.lang = \"es-AR\";\n  window.speechSynthesis.speak(u);\n}\n\nfunction spoken(p: PaymentView) {\n  const pesos = Math.floor(p.amount);\n  const cents = Math.round((p.amount - pesos) * 100);\n  const amount = `${pesos.toLocaleString(\"es-AR\")} pesos${cents ? ` con ${cents} centavos` : \"\"}`;\n  return `Ingresó una transferencia de ${amount} de ${p.senderName || \"un cliente\"}`;\n}\n\nexport function CajaClient({ ocr }: { ocr: boolean }) {\n  const [payments, setPayments] = useState<PaymentView[]>([]);\n  const [voice, setVoice] = useState(false);\n  const [blocked, setBlocked] = useState<string | null>(null);\n  const [msg, setMsg] = useState<{ type: \"ok\" | \"err\"; text: string } | null>(null);\n  const [op, setOp] = useState(\"\");\n  const [verify, setVerify] = useState<VerifyResult | null>(null);\n  const [pending, start] = useTransition();\n\n  const seen = useRef<Set<string>>(new Set());\n  const first = useRef(true);\n  const voiceRef = useRef(false);\n  voiceRef.current = voice;\n\n  const tick = useCallback(async () => {\n    try {\n      const r = await fetch(\"/api/caja/feed\", { cache: \"no-store\" });\n      if (r.status === 401) {\n        window.location.href = \"/caja/login\";\n        return;\n      }\n      if (r.status === 402) {\n        const j = await r.json();\n        setBlocked(j.error ?? \"Servicio suspendido\");\n        return;\n      }\n      const j: { payments: PaymentView[] } = await r.json();\n      const fresh = j.payments.filter((p) => !seen.current.has(p.id));\n      fresh.forEach((p) => seen.current.add(p.id));\n      if (!first.current && voiceRef.current) {\n        fresh.filter((p) => p.status === \"DISPONIBLE\").reverse().forEach((p) => speak(spoken(p)));\n      }\n      first.current = false;\n      setPayments(j.payments);\n    } catch {\n      /* sin conexión: reintenta en el próximo ciclo */\n    }\n  }, []);\n\n  useEffect(() => {\n    tick();\n    const t = setInterval(tick, 3000);\n    return () => clearInterval(t);\n  }, [tick]);\n\n  function validate(id: string) {\n    start(async () => {\n      const r = await validatePayment(id);\n      if (r.ok) setMsg({ type: \"ok\", text: \"Pago validado. Podés entregar.\" });\n      else setMsg({ type: \"err\", text: r.error + (r.usedAt ? ` (validado ${dt(r.usedAt)})` : \"\") });\n      setVerify(null);\n      tick();\n    });\n  }\n\n  function check() {\n    start(async () => {\n      setMsg(null);\n      setVerify(await verifyOperation(op));\n    });\n  }\n\n  if (blocked) {\n    return <p className=\"rounded-xl border border-red-400/40 bg-red-500/10 p-4 text-red-200\">{blocked} Avisale al dueño del comercio.</p>;\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"flex items-center justify-between rounded-xl border border-white/10 bg-white/5 p-3\">\n        <p className=\"text-sm text-white/70\">Aviso por voz de cada cobro</p>\n        <button\n          onClick={() => {\n            const next = !voice;\n            setVoice(next);\n            if (next) speak(\"Aviso por voz activado\");\n          }}\n          className={`rounded-lg px-3 py-1.5 text-sm font-semibold ${voice ? \"bg-[#00cba6] text-[#00070f]\" : \"border border-white/20\"}`}\n        >\n          {voice ? \"Voz activada\" : \"Activar voz\"}\n        </button>\n      </div>\n\n      {msg && (\n        <p className={`rounded-xl p-3 font-semibold ${msg.type === \"ok\" ? \"bg-[#00cba6]/20 text-[#00cba6]\" : \"bg-red-500/20 text-red-300\"}`}>\n          {msg.text}\n        </p>\n      )}\n\n      <section className=\"rounded-xl border border-white/10 bg-white/5 p-4\">\n        <h2 className=\"font-semibold\">Verificar comprobante del cliente</h2>\n        <p className=\"text-xs text-white/60\">Pedile el número de operación que figura en su comprobante.</p>\n        <div className=\"mt-2 flex gap-2\">\n          <input\n            value={op}\n            onChange={(e) => setOp(e.target.value)}\n            inputMode=\"numeric\"\n            placeholder=\"N° de operación\"\n            className=\"flex-1 rounded-lg border border-white/15 bg-white/5 px-3 py-2 font-mono outline-none focus:border-[#00cba6]\"\n          />\n          <button onClick={check} disabled={pending || op.trim().length < 6} className=\"rounded-lg bg-[#00cba6] px-4 font-semibold text-[#00070f] disabled:opacity-50\">\n            Verificar\n          </button>\n        </div>\n        {ocr && <p className=\"mt-2 text-xs text-white/40\">Escáner por cámara (OCR): próximamente en esta versión.</p>}\n\n        {verify && \"error\" in verify && <p className=\"mt-3 text-red-300\">{verify.error}</p>}\n        {verify && \"found\" in verify && !verify.found && (\n          <p className=\"mt-3 rounded-lg bg-red-500/20 p-3 font-semibold text-red-300\">\n            NO ENCONTRADO: ese pago no figura en tu cuenta. Puede ser un comprobante falso o todavía no llegó. No entregues.\n          </p>\n        )}\n        {verify && \"found\" in verify && verify.found && verify.payment.status === \"VALIDADO\" && (\n          <p className=\"mt-3 rounded-lg bg-red-500/20 p-3 font-semibold text-red-300\">\n            COMPROBANTE YA USADO ({verify.payment.validatedAt ? dt(verify.payment.validatedAt) : \"antes\"}). No entregues.\n          </p>\n        )}\n        {verify && \"found\" in verify && verify.found && verify.payment.status === \"DISPONIBLE\" && (\n          <div className=\"mt-3 rounded-lg bg-[#00cba6]/15 p-3\">\n            <p className=\"font-semibold text-[#00cba6]\">ACREDITADO: {money(verify.payment.amount)} de {verify.payment.senderName}</p>\n            <button onClick={() => validate(verify.payment.id)} disabled={pending} className=\"mt-2 rounded-lg bg-[#00cba6] px-4 py-2 font-semibold text-[#00070f]\">\n              Validar y entregar\n            </button>\n          </div>\n        )}\n      </section>\n\n      <section className=\"space-y-3\">\n        <h2 className=\"font-semibold\">Ingresos recientes</h2>\n        {payments.length === 0 && <p className=\"text-white/50\">Esperando transferencias...</p>}\n        {payments.map((p) => (\n          <div\n            key={p.id}\n            className={`flex items-center justify-between rounded-xl border p-4 ${\n              p.status === \"DISPONIBLE\" ? \"border-[#00cba6]/60 bg-[#00cba6]/10\" : \"border-white/10 bg-white/5 opacity-60\"\n            }`}\n          >\n            <div>\n              <p className=\"text-2xl font-bold\">{money(p.amount)}</p>\n              <p className=\"text-sm text-white/70\">{p.senderName || \"Remitente no identificado\"} · {time(p.receivedAt)}</p>\n              <p className=\"font-mono text-xs text-white/40\">Op. {p.externalId}</p>\n            </div>\n            {p.status === \"DISPONIBLE\" ? (\n              <button onClick={() => validate(p.id)} disabled={pending} className=\"rounded-lg bg-[#00cba6] px-4 py-3 font-semibold text-[#00070f] disabled:opacity-60\">\n                Validar y entregar\n              </button>\n            ) : (\n              <span className=\"text-sm text-white/60\">Validado</span>\n            )}\n          </div>\n        ))}\n      </section>\n    </div>\n  );\n}\n",
 "app/caja/login/actions.ts": "\"use server\";\n\nimport bcrypt from \"bcryptjs\";\nimport { redirect } from \"next/navigation\";\nimport { sql } from \"@/lib/db\";\nimport { createSession } from \"@/lib/session\";\nimport { getIp, isBlocked, logAttempt } from \"@/lib/ratelimit\";\n\ntype State = { error?: string } | undefined;\n\nexport async function loginCashier(_prev: State, formData: FormData): Promise<State> {\n  const code = String(formData.get(\"code\") ?? \"\").trim().toUpperCase();\n  const pin = String(formData.get(\"pin\") ?? \"\").trim();\n  const ip = await getIp();\n  const scope = `cashier:${code.slice(0, 12)}`;\n\n  if (!/^[A-Z0-9]{4,12}$/.test(code) || !/^\\d{4}$/.test(pin)) return { error: \"Código de comercio o PIN inválido.\" };\n  if (await isBlocked(ip, scope)) return { error: \"Demasiados intentos. Esperá 15 minutos.\" };\n\n  const rows = await sql`select ca.id, ca.pin_hash from cashiers ca\n    join commerces c on c.id = ca.commerce_id\n    where c.code = ${code} and ca.active = true`;\n\n  let cashierId: string | null = null;\n  for (const r of rows) {\n    if (await bcrypt.compare(pin, r.pin_hash as string)) {\n      cashierId = r.id as string;\n      break;\n    }\n  }\n\n  await logAttempt(ip, scope, cashierId !== null);\n  if (!cashierId) return { error: \"Código de comercio o PIN incorrecto.\" };\n\n  await createSession(\"cashier\", cashierId, 60 * 60 * 12);\n  redirect(\"/caja\");\n}\n",
 "app/caja/login/page.tsx": "\"use client\";\n\nimport { useActionState } from \"react\";\nimport { loginCashier } from \"./actions\";\nimport { inputCls } from \"@/components/ActionForm\";\n\nexport default function CashierLogin() {\n  const [state, action, pending] = useActionState(loginCashier, undefined);\n  return (\n    <main className=\"mx-auto max-w-sm p-8 pt-24\">\n      <h1 className=\"text-2xl font-bold\">Caja</h1>\n      <p className=\"mt-1 text-sm text-white/60\">Ingresá el código de tu comercio y tu PIN.</p>\n      <form action={action} className=\"mt-6 space-y-3\">\n        <input name=\"code\" required autoComplete=\"off\" placeholder=\"Código del comercio\" className={inputCls + \" w-full font-mono uppercase\"} />\n        <input name=\"pin\" required inputMode=\"numeric\" maxLength={4} type=\"password\" placeholder=\"PIN (4 dígitos)\" className={inputCls + \" w-full\"} />\n        {state?.error && <p className=\"text-sm text-red-400\">{state.error}</p>}\n        <button disabled={pending} className=\"w-full rounded-lg bg-[#00cba6] p-3 font-semibold text-[#00070f] disabled:opacity-60\">\n          {pending ? \"Verificando...\" : \"Entrar\"}\n        </button>\n      </form>\n    </main>\n  );\n}\n",
 "app/api/caja/feed/route.ts": "import { NextResponse } from \"next/server\";\nimport { sql } from \"@/lib/db\";\nimport { getCashierContext } from \"@/lib/session\";\n\nexport async function GET() {\n  const ctx = await getCashierContext();\n  if (!ctx) return NextResponse.json({ error: \"No autorizado\" }, { status: 401 });\n  if (ctx.commerce.blocked) {\n    return NextResponse.json({ error: ctx.commerce.blockReason, blocked: true }, { status: 402 });\n  }\n\n  // Privilegio mínimo: solo operaciones recientes, sin saldos ni totales\n  const rows = await sql`select id, external_id, amount, sender_name, status, received_at, validated_at\n    from payments\n    where commerce_id = ${ctx.commerce.id} and received_at > now() - interval '24 hours'\n    order by received_at desc limit 40`;\n\n  return NextResponse.json(\n    {\n      payments: rows.map((r) => ({\n        id: r.id,\n        externalId: r.external_id,\n        amount: Number(r.amount),\n        senderName: r.sender_name,\n        status: r.status,\n        receivedAt: r.received_at,\n        validatedAt: r.validated_at,\n      })),\n    },\n    { headers: { \"Cache-Control\": \"no-store\" } },\n  );\n}\n",
 "app/api/inbound/email/[token]/route.ts": "import { NextResponse } from \"next/server\";\nimport { sql } from \"@/lib/db\";\nimport { insertPayment } from \"@/lib/ingest\";\nimport { parseTransferEmail } from \"@/lib/parse-email\";\nimport { loadCommerce } from \"@/lib/session\";\n\ntype Ctx = { params: Promise<{ token: string }> };\n\nexport async function POST(req: Request, { params }: Ctx) {\n  const { token } = await params;\n  const rows = await sql`select id from commerces where webhook_token = ${token}`;\n  if (!rows[0]) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n\n  const commerce = await loadCommerce(rows[0].id as string);\n  if (!commerce || commerce.blocked) return NextResponse.json({ ignored: \"bloqueado\" });\n\n  let subject = \"\";\n  let text = \"\";\n  let html = \"\";\n  const ct = req.headers.get(\"content-type\") ?? \"\";\n  try {\n    if (ct.includes(\"application/json\")) {\n      const j = await req.json();\n      subject = j.subject ?? j.Subject ?? \"\";\n      text = j.text ?? j.TextBody ?? j[\"body-plain\"] ?? \"\";\n      html = j.html ?? j.HtmlBody ?? j[\"body-html\"] ?? \"\";\n    } else {\n      const f = await req.formData(); // Mailgun, SendGrid, etc.\n      subject = String(f.get(\"subject\") ?? \"\");\n      text = String(f.get(\"body-plain\") ?? f.get(\"text\") ?? \"\");\n      html = String(f.get(\"body-html\") ?? f.get(\"html\") ?? \"\");\n    }\n  } catch {\n    return NextResponse.json({ ignored: \"cuerpo ilegible\" });\n  }\n\n  const parsed = parseTransferEmail({ subject, text, html });\n  if (!parsed) return NextResponse.json({ ignored: \"no parece una transferencia\" });\n\n  const created = await insertPayment({\n    commerceId: commerce.id,\n    externalId: parsed.externalId,\n    amount: parsed.amount,\n    senderName: parsed.senderName,\n    source: \"email\",\n  });\n  return NextResponse.json({ ok: true, created });\n}\n",
 "app/api/webhooks/mercadopago/[token]/route.ts": "import { NextResponse } from \"next/server\";\nimport { sql } from \"@/lib/db\";\nimport { decrypt } from \"@/lib/crypto\";\nimport { insertPayment } from \"@/lib/ingest\";\nimport { loadCommerce } from \"@/lib/session\";\n\ntype Ctx = { params: Promise<{ token: string }> };\n\nexport async function GET() {\n  return NextResponse.json({ ok: true });\n}\n\nexport async function POST(req: Request, { params }: Ctx) {\n  const { token } = await params;\n  const rows = await sql`select id, mp_access_token_enc from commerces where webhook_token = ${token}`;\n  const row = rows[0];\n  if (!row) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n\n  const url = new URL(req.url);\n  let body: { type?: string; topic?: string; action?: string; data?: { id?: string | number } } = {};\n  try {\n    body = await req.json();\n  } catch {\n    /* algunas notificaciones llegan solo por query string */\n  }\n\n  const topic = body.type ?? body.topic ?? url.searchParams.get(\"type\") ?? url.searchParams.get(\"topic\") ?? \"\";\n  const paymentId = String(body.data?.id ?? url.searchParams.get(\"data.id\") ?? url.searchParams.get(\"id\") ?? \"\");\n  if (!topic.startsWith(\"payment\") || !/^\\d+$/.test(paymentId)) return NextResponse.json({ ignored: true });\n\n  const commerce = await loadCommerce(row.id as string);\n  if (!commerce || commerce.blocked || !row.mp_access_token_enc) return NextResponse.json({ ignored: \"bloqueado o sin token\" });\n\n  // Nunca confiamos en el cuerpo de la notificación: consultamos el pago real a Mercado Pago\n  const r = await fetch(`https://api.mercadopago.com/v1/payments/${paymentId}`, {\n    headers: { Authorization: `Bearer ${decrypt(row.mp_access_token_enc as string)}` },\n  });\n  if (!r.ok) return NextResponse.json({ error: \"No pude consultar el pago\" }, { status: 502 }); // MP reintenta\n\n  const p = await r.json();\n  if (p.status !== \"approved\") return NextResponse.json({ ignored: `estado ${p.status}` });\n\n  const name =\n    [p.payer?.first_name, p.payer?.last_name].filter(Boolean).join(\" \").trim() || p.payer?.email || \"Cliente Mercado Pago\";\n  const created = await insertPayment({\n    commerceId: commerce.id,\n    externalId: String(p.id),\n    amount: Number(p.transaction_amount),\n    senderName: name,\n    source: \"mercadopago\",\n  });\n  return NextResponse.json({ ok: true, created });\n}\n",
 "app/login/actions.ts": "\"use server\";\n\nimport bcrypt from \"bcryptjs\";\nimport { redirect } from \"next/navigation\";\nimport { sql } from \"@/lib/db\";\nimport { createSession } from \"@/lib/session\";\nimport { getIp, isBlocked, logAttempt } from \"@/lib/ratelimit\";\n\ntype State = { error?: string } | undefined;\n\nexport async function loginOwner(_prev: State, formData: FormData): Promise<State> {\n  const email = String(formData.get(\"email\") ?? \"\").trim().toLowerCase();\n  const password = String(formData.get(\"password\") ?? \"\");\n  const ip = await getIp();\n\n  if (await isBlocked(ip, \"owner\")) return { error: \"Demasiados intentos. Esperá 15 minutos.\" };\n\n  const rows = await sql`select id, owner_password_hash from commerces where owner_email = ${email} limit 1`;\n  const c = rows[0];\n  const ok = c ? await bcrypt.compare(password, c.owner_password_hash as string) : false;\n\n  await logAttempt(ip, \"owner\", ok);\n  if (!ok || !c) return { error: \"Email o contraseña incorrectos.\" };\n\n  await createSession(\"owner\", c.id as string, 60 * 60 * 24 * 7);\n  redirect(\"/dashboard\");\n}\n",
 "app/login/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { useActionState } from \"react\";\nimport { loginOwner } from \"./actions\";\nimport { inputCls } from \"@/components/ActionForm\";\n\nexport default function OwnerLogin() {\n  const [state, action, pending] = useActionState(loginOwner, undefined);\n  return (\n    <main className=\"mx-auto max-w-sm p-8 pt-24\">\n      <h1 className=\"text-2xl font-bold\">Ingresar a tu comercio</h1>\n      <p className=\"mt-1 text-sm text-white/60\">Acceso para dueños de comercio.</p>\n      <form action={action} className=\"mt-6 space-y-3\">\n        <input name=\"email\" type=\"email\" required placeholder=\"Email\" className={inputCls + \" w-full\"} />\n        <input name=\"password\" type=\"password\" required placeholder=\"Contraseña\" className={inputCls + \" w-full\"} />\n        {state?.error && <p className=\"text-sm text-red-400\">{state.error}</p>}\n        <button disabled={pending} className=\"w-full rounded-lg bg-[#00cba6] p-3 font-semibold text-[#00070f] disabled:opacity-60\">\n          {pending ? \"Verificando...\" : \"Entrar\"}\n        </button>\n      </form>\n      <p className=\"mt-6 text-sm text-white/60\">\n        ¿Sos cajero? <Link href=\"/caja/login\" className=\"text-[#00cba6] underline\">Entrá a la caja</Link>\n      </p>\n    </main>\n  );\n}\n",
 "app/dashboard/actions.ts": "\"use server\";\n\nimport bcrypt from \"bcryptjs\";\nimport { revalidatePath } from \"next/cache\";\nimport { redirect } from \"next/navigation\";\nimport { sql } from \"@/lib/db\";\nimport { encrypt } from \"@/lib/crypto\";\nimport { insertPayment } from \"@/lib/ingest\";\nimport { randomOperationId } from \"@/lib/codes\";\nimport { destroySession, requireOwner } from \"@/lib/session\";\n\ntype Result = { ok?: string; error?: string } | undefined;\nconst BLOCKED: Result = { error: \"Tu cuenta está bloqueada. Renová tu plan para seguir configurando.\" };\n\nexport async function addAccount(_p: Result, fd: FormData): Promise<Result> {\n  const c = await requireOwner();\n  if (c.blocked) return BLOCKED;\n  const label = String(fd.get(\"label\") ?? \"\").trim();\n  const alias = String(fd.get(\"alias\") ?? \"\").trim();\n  const provider = String(fd.get(\"provider\") ?? \"otro\").trim();\n  if (label.length < 2 || label.length > 60 || alias.length < 3 || alias.length > 60) {\n    return { error: \"Completá el nombre y el alias/CVU.\" };\n  }\n  const n = await sql`select count(*)::int as n from accounts where commerce_id = ${c.id}`;\n  if ((n[0].n as number) >= c.plan.accounts) {\n    return { error: `Tu plan permite hasta ${c.plan.accounts} cuenta(s) vinculada(s).` };\n  }\n  await sql`insert into accounts (commerce_id, label, alias_cvu, provider) values (${c.id}, ${label}, ${alias}, ${provider})`;\n  revalidatePath(\"/dashboard\");\n  return { ok: \"Cuenta agregada.\" };\n}\n\nexport async function deleteAccount(id: string): Promise<void> {\n  const c = await requireOwner();\n  await sql`delete from accounts where id = ${id} and commerce_id = ${c.id}`;\n  revalidatePath(\"/dashboard\");\n}\n\nexport async function addCashier(_p: Result, fd: FormData): Promise<Result> {\n  const c = await requireOwner();\n  if (c.blocked) return BLOCKED;\n  const name = String(fd.get(\"name\") ?? \"\").trim();\n  const pin = String(fd.get(\"pin\") ?? \"\").trim();\n  if (name.length < 2 || name.length > 60) return { error: \"Poné el nombre del cajero.\" };\n  if (!/^\\d{4}$/.test(pin)) return { error: \"El PIN debe tener exactamente 4 dígitos.\" };\n\n  const existing = await sql`select pin_hash from cashiers where commerce_id = ${c.id} and active = true`;\n  if (existing.length >= c.plan.cajas) {\n    return { error: `Tu plan permite hasta ${c.plan.cajas} caja(s) con PIN.` };\n  }\n  for (const e of existing) {\n    if (await bcrypt.compare(pin, e.pin_hash as string)) return { error: \"Ese PIN ya está en uso. Elegí otro.\" };\n  }\n  const hash = await bcrypt.hash(pin, 10);\n  await sql`insert into cashiers (commerce_id, name, pin_hash) values (${c.id}, ${name}, ${hash})`;\n  revalidatePath(\"/dashboard\");\n  return { ok: `Cajero creado. Código de comercio: ${c.code} + su PIN.` };\n}\n\nexport async function setCashierActive(id: string, active: boolean): Promise<void> {\n  const c = await requireOwner();\n  if (active) {\n    const n = await sql`select count(*)::int as n from cashiers where commerce_id = ${c.id} and active = true`;\n    if ((n[0].n as number) >= c.plan.cajas) return;\n  }\n  await sql`update cashiers set active = ${active} where id = ${id} and commerce_id = ${c.id}`;\n  revalidatePath(\"/dashboard\");\n}\n\nexport async function deleteCashier(id: string): Promise<void> {\n  const c = await requireOwner();\n  await sql`delete from cashiers where id = ${id} and commerce_id = ${c.id}`;\n  revalidatePath(\"/dashboard\");\n}\n\nexport async function saveMpToken(_p: Result, fd: FormData): Promise<Result> {\n  const c = await requireOwner();\n  if (c.blocked) return BLOCKED;\n  const token = String(fd.get(\"token\") ?? \"\").trim();\n  if (token.length < 20) return { error: \"Pegá el Access Token de producción de tu aplicación de Mercado Pago.\" };\n  try {\n    const r = await fetch(\"https://api.mercadopago.com/users/me\", { headers: { Authorization: `Bearer ${token}` } });\n    if (!r.ok) return { error: \"Mercado Pago rechazó ese token. Revisá que sea el Access Token de producción.\" };\n  } catch {\n    return { error: \"No pude contactar a Mercado Pago. Probá de nuevo.\" };\n  }\n  await sql`update commerces set mp_access_token_enc = ${encrypt(token)} where id = ${c.id}`;\n  revalidatePath(\"/dashboard\");\n  return { ok: \"Mercado Pago vinculado.\" };\n}\n\nexport async function removeMpToken(): Promise<void> {\n  const c = await requireOwner();\n  await sql`update commerces set mp_access_token_enc = null where id = ${c.id}`;\n  revalidatePath(\"/dashboard\");\n}\n\nexport async function simulatePayment(_p: Result, fd: FormData): Promise<Result> {\n  const c = await requireOwner();\n  if (c.blocked) return BLOCKED;\n  const amount = Number(String(fd.get(\"amount\") ?? \"\").replace(\",\", \".\"));\n  const sender = String(fd.get(\"sender\") ?? \"\").trim() || \"Cliente de prueba\";\n  if (!Number.isFinite(amount) || amount <= 0 || amount > 100000000) return { error: \"Monto inválido.\" };\n  await insertPayment({ commerceId: c.id, externalId: randomOperationId(), amount, senderName: sender, source: \"test\" });\n  revalidatePath(\"/dashboard\");\n  return { ok: \"Transferencia de prueba creada: debería sonar en la caja.\" };\n}\n\nexport async function changePassword(_p: Result, fd: FormData): Promise<Result> {\n  const c = await requireOwner();\n  const current = String(fd.get(\"current\") ?? \"\");\n  const next = String(fd.get(\"next\") ?? \"\");\n  if (next.length < 8) return { error: \"La nueva contraseña debe tener 8+ caracteres.\" };\n  const rows = await sql`select owner_password_hash from commerces where id = ${c.id}`;\n  if (!(await bcrypt.compare(current, rows[0].owner_password_hash as string))) {\n    return { error: \"La contraseña actual no es correcta.\" };\n  }\n  await sql`update commerces set owner_password_hash = ${await bcrypt.hash(next, 12)} where id = ${c.id}`;\n  return { ok: \"Contraseña actualizada.\" };\n}\n\nexport async function logoutOwner() {\n  await destroySession(\"owner\");\n  redirect(\"/login\");\n}\n",
 "app/dashboard/page.tsx": "import { Suspense } from \"react\";\nimport { headers } from \"next/headers\";\nimport { sql } from \"@/lib/db\";\nimport { requireOwner } from \"@/lib/session\";\nimport { money, dateTime } from \"@/lib/format\";\nimport { ActionForm, inputCls } from \"@/components/ActionForm\";\nimport {\n  addAccount, addCashier, changePassword, deleteAccount, deleteCashier, logoutOwner,\n  removeMpToken, saveMpToken, setCashierActive, simulatePayment,\n} from \"./actions\";\n\nexport const metadata = { title: \"Mi comercio | ARCREDIX\", robots: { index: false, follow: false } };\n\nexport default function DashboardPage() {\n  return (\n    <Suspense fallback={<main className=\"p-8 text-white/60\">Cargando...</main>}>\n      <DashboardContent />\n    </Suspense>\n  );\n}\n\nconst card = \"rounded-xl border border-white/10 bg-white/5 p-4\";\n\nasync function DashboardContent() {\n  const c = await requireOwner();\n\n  if (c.blocked) {\n    return (\n      <main className=\"mx-auto max-w-xl p-8 pt-24 text-center\">\n        <h1 className=\"text-2xl font-bold\">{c.name}</h1>\n        <p className=\"mt-4 rounded-xl border border-red-400/40 bg-red-500/10 p-4 text-red-200\">\n          {c.blockReason} Contactanos para renovar y reactivar tu acceso y el de tus cajas.\n        </p>\n        <form action={logoutOwner} className=\"mt-6\">\n          <button className=\"text-sm text-white/70 underline\">Cerrar sesión</button>\n        </form>\n      </main>\n    );\n  }\n\n  const h = await headers();\n  const host = h.get(\"x-forwarded-host\") ?? h.get(\"host\") ?? \"tu-dominio.com\";\n  const proto = h.get(\"x-forwarded-proto\") ?? (host.startsWith(\"localhost\") ? \"http\" : \"https\");\n  const base = `${proto}://${host}`;\n\n  const [accounts, cashiers, payments] = await Promise.all([\n    sql`select id, label, alias_cvu, provider from accounts where commerce_id = ${c.id} order by created_at`,\n    sql`select id, name, active from cashiers where commerce_id = ${c.id} order by created_at`,\n    sql`select external_id, amount, sender_name, source, status, received_at, validated_at\n      from payments where commerce_id = ${c.id}\n        and (${c.plan.historyDays}::int is null or received_at > now() - (${c.plan.historyDays}::int * interval '1 day'))\n      order by received_at desc limit 100`,\n  ]);\n\n  return (\n    <main className=\"mx-auto max-w-5xl space-y-6 p-6\">\n      <header className=\"flex flex-wrap items-center justify-between gap-2\">\n        <div>\n          <h1 className=\"text-2xl font-bold\">{c.name}</h1>\n          <p className=\"text-sm text-white/60\">\n            Plan {c.plan.name}\n            {c.lifetime ? \" · licencia vitalicia\" : c.expiresAt ? ` · vence ${c.expiresAt.toLocaleDateString(\"es-AR\")}` : \"\"}\n          </p>\n        </div>\n        <form action={logoutOwner}>\n          <button className=\"text-sm text-white/70 underline\">Cerrar sesión</button>\n        </form>\n      </header>\n\n      <section className={card}>\n        <h2 className=\"font-semibold\">Acceso de tus cajeros</h2>\n        <p className=\"mt-1 text-sm text-white/70\">\n          Código de comercio: <span className=\"font-mono text-lg text-[#00cba6]\">{c.code}</span> · entran en{\" \"}\n          <span className=\"font-mono\">{base}/caja/login</span> con ese código y su PIN de 4 dígitos.\n        </p>\n      </section>\n\n      <section className={card}>\n        <h2 className=\"font-semibold\">Cuentas / alias vinculados ({accounts.length}/{c.plan.accounts})</h2>\n        <ul className=\"my-3 space-y-1 text-sm\">\n          {accounts.map((a) => (\n            <li key={a.id as string} className=\"flex items-center justify-between rounded bg-black/30 px-3 py-2\">\n              <span>{a.label as string} · <span className=\"font-mono\">{a.alias_cvu as string}</span> ({a.provider as string})</span>\n              <form action={deleteAccount.bind(null, a.id as string)}>\n                <button className=\"text-red-300 underline\">Quitar</button>\n              </form>\n            </li>\n          ))}\n          {accounts.length === 0 && <li className=\"text-white/50\">Todavía no cargaste ninguna.</li>}\n        </ul>\n        <ActionForm action={addAccount} submit=\"Agregar\">\n          <input name=\"label\" required placeholder=\"Nombre (ej. Mercado Pago)\" className={inputCls} />\n          <input name=\"alias\" required placeholder=\"Alias o CVU\" className={inputCls} />\n          <select name=\"provider\" className={inputCls} defaultValue=\"mercadopago\">\n            <option value=\"mercadopago\" className=\"text-black\">Mercado Pago</option>\n            <option value=\"banco\" className=\"text-black\">Banco</option>\n            <option value=\"otra\" className=\"text-black\">Otra billetera</option>\n          </select>\n        </ActionForm>\n      </section>\n\n      <section className={card}>\n        <h2 className=\"font-semibold\">Cajeros con PIN ({cashiers.filter((x) => x.active).length}/{c.plan.cajas} activos)</h2>\n        <ul className=\"my-3 space-y-1 text-sm\">\n          {cashiers.map((x) => (\n            <li key={x.id as string} className=\"flex items-center justify-between rounded bg-black/30 px-3 py-2\">\n              <span>{x.name as string} {x.active ? \"\" : <em className=\"text-white/50\">(desactivado)</em>}</span>\n              <span className=\"flex gap-3\">\n                <form action={setCashierActive.bind(null, x.id as string, !x.active)}>\n                  <button className=\"underline\">{x.active ? \"Desactivar\" : \"Activar\"}</button>\n                </form>\n                <form action={deleteCashier.bind(null, x.id as string)}>\n                  <button className=\"text-red-300 underline\">Eliminar</button>\n                </form>\n              </span>\n            </li>\n          ))}\n          {cashiers.length === 0 && <li className=\"text-white/50\">Todavía no creaste cajeros.</li>}\n        </ul>\n        <ActionForm action={addCashier} submit=\"Crear cajero\">\n          <input name=\"name\" required placeholder=\"Nombre del cajero\" className={inputCls} />\n          <input name=\"pin\" required inputMode=\"numeric\" maxLength={4} placeholder=\"PIN (4 dígitos)\" className={inputCls + \" w-40\"} />\n        </ActionForm>\n      </section>\n\n      <section className={card}>\n        <h2 className=\"font-semibold\">Cómo llegan tus cobros</h2>\n        <div className=\"mt-2 space-y-3 text-sm text-white/80\">\n          <div>\n            <p className=\"font-medium text-white\">1) Mercado Pago {c.hasMp && <span className=\"text-[#00cba6]\">· vinculado</span>}</p>\n            <p>Webhook (Notificaciones &gt; Webhooks, evento &quot;Pagos&quot;):</p>\n            <p className=\"break-all rounded bg-black/40 p-2 font-mono text-xs\">{base}/api/webhooks/mercadopago/{c.webhookToken}</p>\n            {c.hasMp ? (\n              <form action={removeMpToken} className=\"mt-2\"><button className=\"text-red-300 underline\">Desvincular Mercado Pago</button></form>\n            ) : (\n              <ActionForm action={saveMpToken} submit=\"Vincular\" className=\"mt-2\">\n                <input name=\"token\" required placeholder=\"Access Token de producción\" className={inputCls + \" min-w-72\"} />\n              </ActionForm>\n            )}\n          </div>\n          <div>\n            <p className=\"font-medium text-white\">2) Correos del banco (reenvío)</p>\n            <p>Configurá el reenvío de las notificaciones bancarias a un servicio de correo entrante que haga POST a:</p>\n            <p className=\"break-all rounded bg-black/40 p-2 font-mono text-xs\">{base}/api/inbound/email/{c.webhookToken}</p>\n          </div>\n        </div>\n      </section>\n\n      <section className={card}>\n        <h2 className=\"font-semibold\">Probar el sistema</h2>\n        <p className=\"mb-2 text-sm text-white/70\">Creá una transferencia de prueba: debería aparecer y sonar en la pantalla de caja.</p>\n        <ActionForm action={simulatePayment} submit=\"Simular transferencia\">\n          <input name=\"amount\" required placeholder=\"Monto (ej. 15000)\" className={inputCls} />\n          <input name=\"sender\" placeholder=\"Remitente (opcional)\" className={inputCls} />\n        </ActionForm>\n      </section>\n\n      <section className={card}>\n        <div className=\"mb-3 flex items-center justify-between\">\n          <h2 className=\"font-semibold\">Historial de comprobantes{c.plan.historyDays ? ` (últimos ${c.plan.historyDays} días)` : \"\"}</h2>\n          <a href=\"/dashboard/export\" className=\"rounded-lg border border-white/20 px-3 py-1.5 text-sm\">Exportar a Excel (CSV)</a>\n        </div>\n        <div className=\"overflow-x-auto\">\n          <table className=\"w-full text-left text-sm\">\n            <thead className=\"text-white/60\">\n              <tr><th className=\"py-1\">Fecha</th><th>N° operación</th><th>Monto</th><th>Remitente</th><th>Origen</th><th>Estado</th></tr>\n            </thead>\n            <tbody>\n              {payments.map((p) => (\n                <tr key={p.external_id as string} className=\"border-t border-white/10\">\n                  <td className=\"py-1.5\">{dateTime(p.received_at as string)}</td>\n                  <td className=\"font-mono\">{p.external_id as string}</td>\n                  <td>{money(p.amount as string)}</td>\n                  <td>{p.sender_name as string}</td>\n                  <td>{p.source as string}</td>\n                  <td>\n                    <span className={p.status === \"VALIDADO\" ? \"text-white/60\" : \"font-semibold text-[#00cba6]\"}>{p.status as string}</span>\n                  </td>\n                </tr>\n              ))}\n              {payments.length === 0 && (\n                <tr><td colSpan={6} className=\"py-3 text-white/50\">Todavía no hay comprobantes.</td></tr>\n              )}\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <section className={card}>\n        <h2 className=\"mb-2 font-semibold\">Cambiar contraseña</h2>\n        <ActionForm action={changePassword} submit=\"Actualizar\">\n          <input name=\"current\" type=\"password\" required placeholder=\"Contraseña actual\" className={inputCls} />\n          <input name=\"next\" type=\"password\" required minLength={8} placeholder=\"Nueva contraseña\" className={inputCls} />\n        </ActionForm>\n      </section>\n    </main>\n  );\n}\n",
 "app/dashboard/export/route.ts": "import { sql } from \"@/lib/db\";\nimport { loadCommerce, readSession } from \"@/lib/session\";\n\nfunction csv(v: unknown) {\n  const s = v === null || v === undefined ? \"\" : String(v);\n  return `\"${s.replace(/\"/g, '\"\"')}\"`;\n}\n\nexport async function GET() {\n  const s = await readSession(\"owner\");\n  if (!s) return new Response(\"No autorizado\", { status: 401 });\n  const c = await loadCommerce(s.sub);\n  if (!c || c.blocked) return new Response(\"Cuenta bloqueada\", { status: 402 });\n\n  const rows = await sql`select received_at, external_id, amount, sender_name, source, status, validated_at\n    from payments where commerce_id = ${c.id}\n      and (${c.plan.historyDays}::int is null or received_at > now() - (${c.plan.historyDays}::int * interval '1 day'))\n    order by received_at desc`;\n\n  const lines = [[\"Fecha\", \"N° operación\", \"Monto\", \"Remitente\", \"Origen\", \"Estado\", \"Validado\"].map(csv).join(\";\")];\n  for (const r of rows) {\n    lines.push(\n      [\n        new Date(r.received_at as string).toLocaleString(\"es-AR\"),\n        r.external_id,\n        String(r.amount).replace(\".\", \",\"),\n        r.sender_name,\n        r.source,\n        r.status,\n        r.validated_at ? new Date(r.validated_at as string).toLocaleString(\"es-AR\") : \"\",\n      ]\n        .map(csv)\n        .join(\";\"),\n    );\n  }\n  // BOM para que Excel respete los acentos\n  return new Response(\"\\uFEFF\" + lines.join(\"\\r\\n\"), {\n    headers: {\n      \"Content-Type\": \"text/csv; charset=utf-8\",\n      \"Content-Disposition\": 'attachment; filename=\"arcredix-comprobantes.csv\"',\n      \"Cache-Control\": \"no-store\",\n    },\n  });\n}\n",
 "scripts/seed-admin.ts": "import bcrypt from \"bcryptjs\";\nimport { neon } from \"@neondatabase/serverless\";\n\nasync function main() {\n  const [email, password] = process.argv.slice(2);\n  if (!email || !password || password.length < 12) {\n    console.error('Uso: npm run admin:create -- correo \"clave de 12+ caracteres\"');\n    process.exit(1);\n  }\n  if (!process.env.DATABASE_URL) {\n    console.error(\"Falta DATABASE_URL (usa npm run admin:create)\");\n    process.exit(1);\n  }\n  const sql = neon(process.env.DATABASE_URL);\n  const hash = await bcrypt.hash(password, 12);\n  await sql`insert into admins (email, password_hash)\n    values (${email.trim().toLowerCase()}, ${hash})\n    on conflict (email) do update set password_hash = excluded.password_hash`;\n  console.log(\"Super-admin listo:\", email);\n}\nmain().catch((e) => {\n  console.error(e);\n  process.exit(1);\n});\n",
 "scripts/schema.ts": "export const statements = [\n  `create table if not exists admins (\n    id uuid primary key default gen_random_uuid(),\n    email text not null unique,\n    password_hash text not null,\n    created_at timestamptz not null default now()\n  )`,\n  `create table if not exists commerces (\n    id uuid primary key default gen_random_uuid(),\n    name text not null,\n    owner_email text not null unique,\n    owner_password_hash text not null,\n    plan text not null default 'starter',\n    status text not null default 'active',\n    lifetime boolean not null default false,\n    expires_at timestamptz,\n    code text not null unique,\n    webhook_token text not null unique,\n    mp_access_token_enc text,\n    created_at timestamptz not null default now()\n  )`,\n  `create table if not exists accounts (\n    id uuid primary key default gen_random_uuid(),\n    commerce_id uuid not null references commerces(id) on delete cascade,\n    label text not null,\n    alias_cvu text not null,\n    provider text not null default 'otro',\n    created_at timestamptz not null default now()\n  )`,\n  `create table if not exists cashiers (\n    id uuid primary key default gen_random_uuid(),\n    commerce_id uuid not null references commerces(id) on delete cascade,\n    name text not null,\n    pin_hash text not null,\n    active boolean not null default true,\n    created_at timestamptz not null default now()\n  )`,\n  `create table if not exists payments (\n    id uuid primary key default gen_random_uuid(),\n    commerce_id uuid not null references commerces(id) on delete cascade,\n    external_id text not null,\n    amount numeric(14,2) not null,\n    sender_name text not null default '',\n    source text not null,\n    status text not null default 'DISPONIBLE',\n    received_at timestamptz not null default now(),\n    validated_at timestamptz,\n    validated_by uuid references cashiers(id) on delete set null,\n    unique (commerce_id, external_id)\n  )`,\n  `create index if not exists idx_payments_commerce on payments (commerce_id, received_at desc)`,\n  `create table if not exists login_attempts (\n    id bigserial primary key,\n    ip text not null,\n    scope text not null,\n    success boolean not null default false,\n    created_at timestamptz not null default now()\n  )`,\n  `create index if not exists idx_attempts on login_attempts (scope, ip, created_at)`,\n];\n",
 "scripts/setup-db.ts": "import { neon } from \"@neondatabase/serverless\";\nimport { statements } from \"./schema\";\n\nasync function main() {\n  if (!process.env.DATABASE_URL) {\n    console.error(\"Falta DATABASE_URL. Usa: npm run db:setup\");\n    process.exit(1);\n  }\n  const sql = neon(process.env.DATABASE_URL);\n  for (const s of statements) await sql.query(s);\n  console.log(\"Tablas listas: admins, commerces, accounts, cashiers, payments, login_attempts\");\n}\nmain().catch((e) => {\n  console.error(e);\n  process.exit(1);\n});\n",
 "lib/codes.ts": "import { randomBytes, randomInt } from \"node:crypto\";\n\n// Sin 0, O, 1, I para evitar confusiones al dictar o copiar\nconst ALPHABET = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\";\n\n/** Código corto del comercio (lo usan los cajeros junto con su PIN). Ej: K7F2QX */\nexport function generateCommerceCode(size = 6): string {\n  let out = \"\";\n  for (let i = 0; i < size; i++) out += ALPHABET[randomInt(ALPHABET.length)];\n  return out;\n}\n\n/** Token secreto para las URLs de webhook / reenvío de correos de cada comercio */\nexport function generateToken(): string {\n  return randomBytes(24).toString(\"base64url\");\n}\n\nexport function randomOperationId(): string {\n  let out = \"9\";\n  for (let i = 0; i < 11; i++) out += randomInt(10);\n  return out;\n}\n",
 "lib/session.ts": "import { cookies } from \"next/headers\";\nimport { redirect } from \"next/navigation\";\nimport { sql } from \"./db\";\nimport { isPlanId, PLANS, type Plan, type PlanId } from \"./plans\";\nimport { COOKIE, type Role, signToken, verifyToken } from \"./token\";\n\nexport async function createSession(role: Role, sub: string, maxAgeSec: number) {\n  const token = await signToken(role, sub, maxAgeSec);\n  (await cookies()).set(COOKIE[role], token, {\n    httpOnly: true,\n    secure: process.env.NODE_ENV === \"production\",\n    sameSite: \"lax\",\n    path: \"/\",\n    maxAge: maxAgeSec,\n  });\n}\n\nexport async function destroySession(role: Role) {\n  (await cookies()).delete(COOKIE[role]);\n}\n\nexport async function readSession(role: Role) {\n  const token = (await cookies()).get(COOKIE[role])?.value;\n  return verifyToken(token, role);\n}\n\nexport type Commerce = {\n  id: string;\n  name: string;\n  ownerEmail: string;\n  planId: PlanId;\n  plan: Plan;\n  status: string;\n  lifetime: boolean;\n  expiresAt: Date | null;\n  code: string;\n  webhookToken: string;\n  hasMp: boolean;\n  blocked: boolean;\n  blockReason: string | null;\n};\n\nexport async function loadCommerce(id: string): Promise<Commerce | null> {\n  const rows = await sql`select id, name, owner_email, plan, status, lifetime, expires_at, code,\n      webhook_token, (mp_access_token_enc is not null) as has_mp\n    from commerces where id = ${id}`;\n  const r = rows[0];\n  if (!r) return null;\n  const planId = (isPlanId(r.plan as string) ? r.plan : \"starter\") as PlanId;\n  const expiresAt = r.expires_at ? new Date(r.expires_at as string) : null;\n  const lifetime = Boolean(r.lifetime);\n  const suspended = r.status === \"suspended\";\n  const expired = !lifetime && expiresAt !== null && expiresAt.getTime() < Date.now();\n  return {\n    id: r.id as string,\n    name: r.name as string,\n    ownerEmail: r.owner_email as string,\n    planId,\n    plan: PLANS[planId],\n    status: r.status as string,\n    lifetime,\n    expiresAt,\n    code: r.code as string,\n    webhookToken: r.webhook_token as string,\n    hasMp: Boolean(r.has_mp),\n    blocked: suspended || expired,\n    blockReason: suspended ? \"Tu cuenta está suspendida.\" : expired ? \"Tu suscripción venció.\" : null,\n  };\n}\n\nexport async function requireAdmin() {\n  const s = await readSession(\"admin\");\n  if (!s) redirect(\"/admin/login\");\n  return s;\n}\n\nexport async function requireOwner(): Promise<Commerce> {\n  const s = await readSession(\"owner\");\n  if (!s) redirect(\"/login\");\n  const c = await loadCommerce(s.sub);\n  if (!c) redirect(\"/login\");\n  return c;\n}\n\nexport async function getCashierContext() {\n  const s = await readSession(\"cashier\");\n  if (!s) return null;\n  const rows = await sql`select id, name, commerce_id from cashiers where id = ${s.sub} and active = true`;\n  const cashier = rows[0];\n  if (!cashier) return null;\n  const commerce = await loadCommerce(cashier.commerce_id as string);\n  if (!commerce) return null;\n  return { cashier: { id: cashier.id as string, name: cashier.name as string }, commerce };\n}\n\nexport async function requireCashier() {\n  const ctx = await getCashierContext();\n  if (!ctx) redirect(\"/caja/login\");\n  return ctx;\n}\n",
 "lib/format.ts": "export function money(n: number | string) {\n  return Number(n).toLocaleString(\"es-AR\", { style: \"currency\", currency: \"ARS\", maximumFractionDigits: 2 });\n}\n\nexport function dateTime(d: string | Date) {\n  return new Date(d).toLocaleString(\"es-AR\", { dateStyle: \"short\", timeStyle: \"short\" });\n}\n",
 "lib/ratelimit.ts": "import { headers } from \"next/headers\";\nimport { sql } from \"./db\";\n\nconst WINDOW_MIN = 15;\nconst MAX_FAILS_PER_IP = 5;\nconst MAX_FAILS_PER_SCOPE = 30; // todas las IPs juntas (protege los PIN de 4 dígitos)\n\nexport async function getIp() {\n  const h = await headers();\n  return h.get(\"x-forwarded-for\")?.split(\",\")[0]?.trim() || h.get(\"x-real-ip\") || \"unknown\";\n}\n\n/** scope: \"admin\" | \"owner\" | \"cashier:CODIGO\" */\nexport async function isBlocked(ip: string, scope: string) {\n  const rows = await sql`select\n      count(*) filter (where ip = ${ip})::int as by_ip,\n      count(*)::int as by_scope\n    from login_attempts\n    where scope = ${scope} and success = false\n      and created_at > now() - (${WINDOW_MIN} * interval '1 minute')`;\n  return (rows[0].by_ip as number) >= MAX_FAILS_PER_IP || (rows[0].by_scope as number) >= MAX_FAILS_PER_SCOPE;\n}\n\nexport async function logAttempt(ip: string, scope: string, success: boolean) {\n  await sql`insert into login_attempts (ip, scope, success) values (${ip}, ${scope}, ${success})`;\n}\n",
 "lib/ingest.ts": "import { sql } from \"./db\";\n\nexport type IncomingPayment = {\n  commerceId: string;\n  externalId: string; // número de operación (único por comercio)\n  amount: number;\n  senderName: string;\n  source: \"mercadopago\" | \"email\" | \"test\";\n};\n\n/** Inserta el pago como DISPONIBLE. Devuelve false si ya existía (idempotente). */\nexport async function insertPayment(p: IncomingPayment): Promise<boolean> {\n  const rows = await sql`insert into payments (commerce_id, external_id, amount, sender_name, source)\n    values (${p.commerceId}, ${p.externalId}, ${p.amount}, ${p.senderName}, ${p.source})\n    on conflict (commerce_id, external_id) do nothing\n    returning id`;\n  return rows.length > 0;\n}\n",
 "lib/config.ts": "// Número de WhatsApp para los botones de compra (formato internacional sin +, ej: 5492230000000)\nexport const WHATSAPP = process.env.NEXT_PUBLIC_WHATSAPP ?? \"\";\n\nexport function buyLink(plan: string) {\n  const text = encodeURIComponent(`Hola! Quiero contratar ARCREDIX - ${plan}`);\n  return WHATSAPP ? `https://wa.me/${WHATSAPP}?text=${text}` : \"/login\";\n}\n",
 "lib/crypto.ts": "import { createCipheriv, createDecipheriv, randomBytes } from \"node:crypto\";\n\nfunction key() {\n  const k = process.env.ENCRYPTION_KEY;\n  if (!k) throw new Error(\"Falta ENCRYPTION_KEY\");\n  const buf = Buffer.from(k, \"base64\");\n  if (buf.length !== 32) throw new Error(\"ENCRYPTION_KEY debe ser de 32 bytes en base64\");\n  return buf;\n}\n\n/** AES-256-GCM. Formato: iv.tag.cifrado (base64url) */\nexport function encrypt(plain: string): string {\n  const iv = randomBytes(12);\n  const c = createCipheriv(\"aes-256-gcm\", key(), iv);\n  const enc = Buffer.concat([c.update(plain, \"utf8\"), c.final()]);\n  return [iv, c.getAuthTag(), enc].map((b) => b.toString(\"base64url\")).join(\".\");\n}\n\nexport function decrypt(payload: string): string {\n  const [iv, tag, enc] = payload.split(\".\").map((p) => Buffer.from(p, \"base64url\"));\n  const d = createDecipheriv(\"aes-256-gcm\", key(), iv);\n  d.setAuthTag(tag);\n  return Buffer.concat([d.update(enc), d.final()]).toString(\"utf8\");\n}\n",
 "lib/db.ts": "import { neon } from \"@neondatabase/serverless\";\n\nconst url = process.env.DATABASE_URL;\nif (!url) throw new Error(\"Falta DATABASE_URL en .env.local (o en las variables de Vercel)\");\n\n// Uso: const rows = await sql`select * from commerces where id = ${id}`;\nexport const sql = neon(url);\n",
 "lib/parse-email.ts": "import { createHash } from \"node:crypto\";\n\nexport type ParsedTransfer = { amount: number; externalId: string; senderName: string };\n\n/** \"1.234,56\" -> 1234.56 | \"1234.56\" -> 1234.56 | \"15.000\" -> 15000 */\nexport function parseArgAmount(raw: string): number {\n  const s = raw.trim();\n  if (s.includes(\",\")) return Number(s.replace(/\\./g, \"\").replace(\",\", \".\"));\n  if (/^\\d+\\.\\d{1,2}$/.test(s)) return Number(s);\n  return Number(s.replace(/\\./g, \"\"));\n}\n\nfunction stripHtml(html: string) {\n  return html\n    .replace(/<style[\\s\\S]*?<\\/style>/gi, \" \")\n    .replace(/<[^>]+>/g, \" \")\n    .replace(/&nbsp;/g, \" \")\n    .replace(/&amp;/g, \"&\")\n    .replace(/\\s+/g, \" \");\n}\n\n/**\n * Parser genérico y \"mejor esfuerzo\" para correos de notificación bancaria.\n * Cada banco usa su propio formato: probalo con correos reales y ajustá las regex.\n */\nexport function parseTransferEmail(input: { subject?: string; text?: string; html?: string }): ParsedTransfer | null {\n  const body = [input.subject ?? \"\", input.text || (input.html ? stripHtml(input.html) : \"\")].join(\" \\n \").replace(/\\s+/g, \" \");\n\n  const amountMatch = body.match(/\\$\\s?(\\d{1,3}(?:\\.\\d{3})*(?:,\\d{1,2})?|\\d+(?:[.,]\\d{1,2})?)/);\n  if (!amountMatch) return null;\n  const amount = parseArgAmount(amountMatch[1]);\n  if (!Number.isFinite(amount) || amount <= 0) return null;\n\n  const opMatch = body.match(/(?:operaci[oó]n|referencia|comprobante|transacci[oó]n|c[oó]digo|id)\\D{0,25}(\\d{6,})/i);\n  const externalId = opMatch\n    ? opMatch[1]\n    : \"h\" + createHash(\"sha1\").update(body).digest(\"hex\").slice(0, 16); // sin Nº de operación: id derivado del contenido\n\n  const NAME = \"([A-ZÁÉÍÓÚÑ][\\\\p{L}.'-]+(?:\\\\s+[A-ZÁÉÍÓÚÑ][\\\\p{L}.'-]+){0,4})\";\n  const patterns = [\n    new RegExp(NAME + \"\\\\s+te\\\\s+envi[oó]\", \"u\"), // \"Juan Pérez te envió $ 15.000\"\n    new RegExp(\"(?:[Dd]e parte de|[Rr]emitente|[Oo]rigen|[Ee]nviado por|[Tt]ransferencia de|[Tt]itular)\\\\s*:?\\\\s*\" + NAME, \"u\"),\n  ];\n  let senderName = \"Remitente no identificado\";\n  for (const re of patterns) {\n    const m = body.match(re);\n    if (m) {\n      senderName = m[1].trim();\n      break;\n    }\n  }\n\n  return { amount, externalId, senderName };\n}\n",
 "lib/token.ts": "import { SignJWT, jwtVerify } from \"jose\";\n\nexport type Role = \"admin\" | \"owner\" | \"cashier\";\nexport const COOKIE: Record<Role, string> = {\n  admin: \"arc_admin\",\n  owner: \"arc_owner\",\n  cashier: \"arc_cashier\",\n};\n\nfunction key() {\n  const s = process.env.SESSION_SECRET;\n  if (!s) throw new Error(\"Falta SESSION_SECRET\");\n  return new TextEncoder().encode(s);\n}\n\nexport async function signToken(role: Role, sub: string, maxAgeSec: number) {\n  return new SignJWT({ role })\n    .setProtectedHeader({ alg: \"HS256\" })\n    .setSubject(sub)\n    .setIssuedAt()\n    .setExpirationTime(`${maxAgeSec}s`)\n    .sign(key());\n}\n\nexport async function verifyToken(token: string | undefined, role: Role) {\n  if (!token) return null;\n  try {\n    const { payload } = await jwtVerify(token, key(), { algorithms: [\"HS256\"] });\n    if (payload.role !== role || !payload.sub) return null;\n    return { sub: payload.sub };\n  } catch {\n    return null;\n  }\n}\n",
 "lib/plans.ts": "export type PlanId = \"starter\" | \"pro\" | \"enterprise\" | \"lifetime\";\n\nexport type Plan = {\n  name: string;\n  priceMonthly: number | null; // USD por mes (null = pago único)\n  setup: number; // USD (en lifetime es el pago único)\n  cajas: number; // cajas / PINs de cajero máximos\n  accounts: number; // alias / CVU / bancos vinculados\n  ocr: boolean; // escáner por cámara habilitado\n  historyDays: number | null; // null = ilimitado\n};\n\nexport const PLANS: Record<PlanId, Plan> = {\n  starter: { name: \"Starter Mostrador\", priceMonthly: 15, setup: 30, cajas: 1, accounts: 1, ocr: false, historyDays: 30 },\n  pro: { name: \"Comercio Pro\", priceMonthly: 29, setup: 50, cajas: 4, accounts: 3, ocr: true, historyDays: null },\n  enterprise: { name: \"Empresa & Distribución\", priceMonthly: 55, setup: 90, cajas: 999, accounts: 999, ocr: true, historyDays: null },\n  lifetime: { name: \"Licencia Propia\", priceMonthly: null, setup: 390, cajas: 4, accounts: 3, ocr: true, historyDays: null },\n};\n\nexport function isPlanId(x: string): x is PlanId {\n  return x in PLANS;\n}\n"
};

const BIN_FILES = {"public/arcredix-logo.webp": "", "app/icon.png": ""};

const PROXY = "import { NextResponse, type NextRequest } from \"next/server\";\nimport { COOKIE, verifyToken } from \"@/lib/token\";\n\nexport async function middleware(req: NextRequest) {\n  const { pathname } = req.nextUrl;\n\n  if (pathname.startsWith(\"/admin\") && pathname !== \"/admin/login\") {\n    const ok = await verifyToken(req.cookies.get(COOKIE.admin)?.value, \"admin\");\n    if (!ok) return NextResponse.redirect(new URL(\"/admin/login\", req.url));\n  }\n  if (pathname.startsWith(\"/dashboard\")) {\n    const ok = await verifyToken(req.cookies.get(COOKIE.owner)?.value, \"owner\");\n    if (!ok) return NextResponse.redirect(new URL(\"/login\", req.url));\n  }\n  if (pathname.startsWith(\"/caja\") && pathname !== \"/caja/login\") {\n    const ok = await verifyToken(req.cookies.get(COOKIE.cashier)?.value, \"cashier\");\n    if (!ok) return NextResponse.redirect(new URL(\"/caja/login\", req.url));\n  }\n  return NextResponse.next();\n}\n\nexport const config = { matcher: [\"/admin/:path*\", \"/dashboard/:path*\", \"/caja/:path*\"] };\n";

const ENV_EXAMPLE = "# Copiá este archivo como .env.local y completá los valores\nDATABASE_URL=\"postgresql://USUARIO:CLAVE@ep-xxxx-pooler.REGION.aws.neon.tech/neondb?sslmode=require\"\n# Generá cada secreto con: node -e \"console.log(require('crypto').randomBytes(32).toString('base64'))\"\nSESSION_SECRET=\"\"\nENCRYPTION_KEY=\"\"\n# Número de WhatsApp para los botones \"Contratar\" (formato internacional sin +, ej: 5492230000000)\nNEXT_PUBLIC_WHATSAPP=\"\"\n";


const read = (rel) => {
  const abs = path.join(root, rel);
  return fs.existsSync(abs) ? fs.readFileSync(abs, "utf8") : "";
};
const isTemplate = (rel) => {
  const c = read(rel);
  return c === "" ? false : /create-next-app|next\.svg|Create Next App|get started by editing|To get started/i.test(c);
};

// La landing y el layout reemplazan a los de la plantilla por defecto de Next
const REPLACE_IF_TEMPLATE = new Set(["app/page.tsx", "app/layout.tsx"]);

function writeText(rel, content) {
  const abs = path.join(root, rel);
  const exists = fs.existsSync(abs);
  if (exists && !FORCE && !(REPLACE_IF_TEMPLATE.has(rel) && isTemplate(rel))) {
    skip(rel + " ya existe (usa --force para sobrescribir)");
    return;
  }
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content, "utf8");
  ok(rel + (exists ? " (reemplazado)" : ""));
}
function writeBin(rel, b64) {
  const abs = path.join(root, rel);
  if (fs.existsSync(abs) && !FORCE) {
    skip(rel + " ya existe");
    return;
  }
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, Buffer.from(b64, "base64"));
  ok(rel);
}

log("\n1) Creando archivos de ARCREDIX...");
const templateProject = isTemplate("app/page.tsx");
for (const [rel, content] of Object.entries(TEXT_FILES)) writeText(rel, content);
for (const [rel, b64] of Object.entries(BIN_FILES)) writeBin(rel, b64);
if (nextMajor >= 16) {
  writeText("proxy.ts", PROXY.replace("export async function middleware", "export async function proxy"));
} else {
  writeText("middleware.ts", PROXY);
}
// el favicon por defecto de la plantilla pisaria al icono de ARCREDIX (app/icon.png)
const fav = path.join(root, "app", "favicon.ico");
if (templateProject && fs.existsSync(fav)) {
  fs.rmSync(fav);
  ok("app/favicon.ico de la plantilla eliminado (se usa app/icon.png)");
}

log("\n2) Variables de entorno...");
const secret = () => crypto.randomBytes(32).toString("base64");
const envPath = path.join(root, ".env.local");
if (fs.existsSync(envPath)) {
  let env = fs.readFileSync(envPath, "utf8");
  let changed = false;
  const need = { SESSION_SECRET: secret(), ENCRYPTION_KEY: secret(), NEXT_PUBLIC_WHATSAPP: "", DATABASE_URL: "PEGA_AQUI_TU_CADENA_DE_NEON" };
  for (const [k, v] of Object.entries(need)) {
    if (!new RegExp("^" + k + "=", "m").test(env)) {
      env += (env.endsWith("\n") || env === "" ? "" : "\n") + k + '="' + v + '"\n';
      changed = true;
      ok("agregado " + k + " a .env.local");
    }
  }
  if (changed) fs.writeFileSync(envPath, env, "utf8");
  else skip(".env.local ya tiene las variables");
} else {
  const env = ENV_EXAMPLE
    .replace('SESSION_SECRET=""', 'SESSION_SECRET="' + secret() + '"')
    .replace('ENCRYPTION_KEY=""', 'ENCRYPTION_KEY="' + secret() + '"');
  fs.writeFileSync(envPath, env, "utf8");
  ok(".env.local creado con SESSION_SECRET y ENCRYPTION_KEY generados");
}
fs.writeFileSync(path.join(root, ".env.example"), ENV_EXAMPLE, "utf8");

const giPath = path.join(root, ".gitignore");
const gi = fs.existsSync(giPath) ? fs.readFileSync(giPath, "utf8") : "";
if (!/^\.env/m.test(gi)) {
  fs.appendFileSync(giPath, "\n# secretos\n.env*\n!.env.example\n");
  ok(".gitignore actualizado");
}

log("\n3) Scripts de npm...");
pkg.scripts = pkg.scripts || {};
pkg.scripts["db:setup"] = "tsx --env-file=.env.local scripts/setup-db.ts";
pkg.scripts["admin:create"] = "tsx --env-file=.env.local scripts/seed-admin.ts";
fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n", "utf8");
ok('agregados "db:setup" y "admin:create"');

if (NO_INSTALL) {
  log("\n4) Instalacion omitida. Instala a mano:\n   npm i @neondatabase/serverless jose bcryptjs zod\n   npm i -D tsx");
} else {
  log("\n4) Instalando dependencias (puede tardar un minuto)...");
  try {
    execSync("npm i @neondatabase/serverless jose bcryptjs zod", { stdio: "inherit" });
    execSync("npm i -D tsx", { stdio: "inherit" });
  } catch {
    console.error("\nFallo la instalacion. Ejecuta a mano:\n  npm i @neondatabase/serverless jose bcryptjs zod\n  npm i -D tsx");
  }
}

